/* ページ全体 */
.login-page {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    background: #f2f4f8;
    padding: 20px;
  }
  
  /* カード型 */
  .login-card {
    background: #ffffff;
    padding: 40px 30px;
    border-radius: 12px;
    box-shadow: 0 8px 20px rgba(0,0,0,0.1);
    width: 100%;
    max-width: 400px;
    text-align: center;
  }
  
  /* タイトル */
  .login-card h2 {
    margin-bottom: 30px;
    color: #333;
  }
  
  /* フォーム */
  .form-group {
    margin-bottom: 20px;
    text-align: left;
  }
  
  .form-group label {
    display: block;
    margin-bottom: 5px;
    font-weight: bold;
  }
  
  .form-control {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 14px;
  }
  
  /* ボタン */
  .btn-login {
    width: 100%;
    padding: 12px;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 16px;
    cursor: pointer;
    transition: background 0.2s;
  }
  
  .btn-login:hover {
    background-color: #0056b3;
  }
  
  /* オプション */
  .form-options {
    margin-bottom: 15px;
    font-size: 14px;
  }
  
  .login-links {
    margin-top: 20px;
    font-size: 14px;
  }
  
  .login-links a {
    color: #007bff;
    text-decoration: none;
  }
  
  .login-links a:hover {
    text-decoration: underline;
  }
